 "content": "def transform(grid):
    # Fill cells between each 1-marker and its corresponding boundary with color 1;
    # diagonal 3s become 4, and the diagonal trail extends rightward as 1s.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # 1s on first/last rows mark horizontal spans: continue fill between them.
    for r in range(h):
        ones = [c for c, v in enumerate(g[r]) if v == 1]
        if ones:
            for c in range(min(ones), max(ones) + 1):
                if g[r][c] == 0:
                    g[r][c] = 1
    # Diagonal objects: turn 3 into 4 and fill rightward on that row with 1,
    # preserving nonzero edge boundary cells.
    for r in range(h):
        for c in range(w):
            if g[r][c] == 3:
                g[r][c] = 4
                for k in range(c + 1, w):
                    if g[r][k] == 0:
                        g[r][k] = 1
    return g
"
