    # non-background framing cell; marker changes to 4 (as in the demos).
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in (1, 3):
                continue
            g[r][c] = 4
            # Find boundary stripe(s) on the same row. In demo 1 and 2,
            # the seed is extended toward the framing stripe on its left/right.
            left = next((k for k in range(c-1, -1, -1) if grid[r][k] != bg), None)
            right = next((k for k in range(c+1, w) if grid[r][k] != bg), None)
            if left is not None and right is not None:
                a, b = left+1, right
            elif left is not None:
                a, b = left+1, c
            elif right is not None:
                a, b = c+1, right
            else:
                continue
