                if grid[r][k] == bg:
                    g[r][k] = 1
    # Task's 3 trail represents slanted line segments; fill between two 3s
    # appearing in a row, and do not alter empty rows.
    for r in range(h):
        marks = [c for c, v in enumerate(grid[r]) if v == 3]
        for a, b in zip(marks, marks[1:]):
            for c in range(a+1, b):
                if grid[r][c] == bg:
                    g[r][c] = 1
    return g
