    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The 3s are points on a staircase diagonal; continue the staircase
    # through the gaps, converting the original points to 4.
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    for r, c in points:
        out[r][c] = 4
    for (r1, c1), (r2, c2) in zip(points, points[1:]):
        # Intermediate diagonal stair-step cells on the path between markers.
        dr, dc = r2-r1, c2-c1
        if dr > 0 and dc > 0:
            for k in range(1, min(dr, dc)):
                rr, cc = r1+k, c1+k
                if grid[rr][cc] == 9:
                    out[rr][cc] = 3
    return out
